/* ============ extra-dex.js — the species and forms MrSurvivor adds (MrSurvivor fork) ============
 * Upstream's Pokédex (js/data/pokedex.js) has the species whose SpriteCollab base folder has sheets. The fork
 * adds, from js/fork/extra-dex-data.js (generated by fork/fetch-extra-dex.py):
 *   - species whose only finished sheets are a form's (Miraidon, Ting-Lu, Gimmighoul, Falinks) or that were
 *     finished after upstream's fetch (Rolycoly), at their own dex number;
 *   - regional forms (Alola, Galar, Hisui, Paldea) and forms the games treat as a Pokémon of their own (Rotom's
 *     appliances, Origin Forme, Therian Forme, Black/White Kyurem, Female Meowstic...), numbered from 1501 with
 *     `base` = their species' dex number.
 * They are full Pokémon everywhere: collection, gacha banners (by the generation that introduced them), wild
 * enemies, rifts for the legendary ones, trading, the Player Manager. Learnsets, run abilities and evolutions
 * come from js/fork/lab/lab-data.js (fork/fetch-lab.cjs reads extra-dex-data.js too).
 * Loaded right after js/data/tms.js, before anything reads G.DEX: the rows go into G.DEX next to their species,
 * G.DEX_BY, G.SPRITE_META and G.DEX_ABIL. A row upstream has meanwhile added itself is skipped.
 *   G.dexNo(p or dex)  the number to show and sort by: a form shows its species' (Alolan Raichu is Nº 026)
 * Test: fork/test-extra-dex.cjs.
 */
(() => {
  const D = G.FORK_DEX || [], SPR = G.FORK_DEX_SPRITES || {}, AB = G.FORK_DEX_ABIL || {};
  const no = p => p.base || p.dex;
  const added = [];
  for (const e of D) {
    if (G.DEX_BY[e.dex] || !SPR[e.dex]) continue;
    // Next to its species: after every row with the same or a lower number.
    let i = G.DEX.findIndex(p => no(p) > no(e));
    if (i < 0) i = G.DEX.length;
    G.DEX.splice(i, 0, e);
    G.DEX_BY[e.dex] = e;
    G.SPRITE_META[e.dex] = SPR[e.dex];
    if (G.DEX_ABIL && AB[e.dex]) G.DEX_ABIL[e.dex] = AB[e.dex];
    added.push(e);
  }

  G.dexNo = x => {
    const p = x && typeof x === 'object' ? x : G.DEX_BY[x];
    return p ? no(p) : +x || 0;
  };

  // TMs: upstream's list (js/data/tms.js) names species by number, so the added ones take theirs from their
  // learnsets (the moves they learn by TM in the games that the Kecleon Shop sells).
  // (The Radiant Kit page and the radiant tools load the data without the rest of the game.)
  const ADDED = new Set(added.map(e => e.dex));
  const tmOf = G.TM_OF;
  if (tmOf) G.TM_OF = dex => {
    if (!ADDED.has(+dex) || !G.LabData || !G.LabData.learn[dex]) return tmOf(dex);
    const L = G.LabData, tm = (L.learn[dex].split('|')[3] || '').split(',').filter(Boolean);
    return tm.map(i => L.MOVES[parseInt(i, 36)]).filter(id => G.TM_MOVES[id]);
  };

  // Their names are English already: kept as they are (the word-by-word pass would change "Heat" or "Sky").
  if (G.I18n) G.I18n.add(Object.fromEntries(added.map(e => [e.name, e.name])), 'en');
})();
